        # [doc = " Due to the `Stream` trait's inclusion in `std` landing later than Tokio's 1.0"] # [doc = " release, most of the Tokio stream utilities have been moved into the [`tokio-stream`]"] # [doc = " crate."] # [doc = ""] # [doc = " # Why was `Stream` not included in Tokio 1.0?"] # [doc = ""] # [doc = " Originally, we had planned to ship Tokio 1.0 with a stable `Stream` type"] # [doc = " but unfortunately the [RFC] had not been merged in time for `Stream` to"] # [doc = " reach `std` on a stable compiler in time for the 1.0 release of Tokio. For"] # [doc = " this reason, the team has decided to move all `Stream` based utilities to"] # [doc = " the [`tokio-stream`] crate. While this is not ideal, once `Stream` has made"] # [doc = " it into the standard library and the `MSRV` period has passed, we will implement"] # [doc = " stream for our different types."] # [doc = ""] # [doc = " While this may seem unfortunate, not all is lost as you can get much of the"] # [doc = " `Stream` support with `async/await` and `while let` loops. It is also possible"] # [doc = " to create a `impl Stream` from `async fn` using the [`async-stream`] crate."] # [doc = ""] # [doc = " [`tokio-stream`]: https://docs.rs/tokio-stream"] # [doc = " [`async-stream`]: https://docs.rs/async-stream"] # [doc = " [RFC]: https://github.com/rust-lang/rfcs/pull/2996"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " Convert a [`sync::mpsc::Receiver`] to an `impl Stream`."] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " use tokio::sync::mpsc;"] # [doc = ""] # [doc = " let (tx, mut rx) = mpsc::channel::<usize>(16);"] # [doc = ""] # [doc = " let stream = async_stream::stream! {"] # [doc = "     while let Some(item) = rx.recv().await {"] # [doc = "         yield item;"] # [doc = "     }"] # [doc = " };"] # [doc = " ```"] pub mod stream { }
